import { HistoricalDocument } from '../../types';

export const ordenacoesLivro1TitulosXiAXx: HistoricalDocument = {
  id: 'ordenacoes-livro-1-titulos-xi-a-xx',
  title: 'Ordenações Filipinas — Títulos XI a XX',
  subtitle: 'Dos Ouvidores do Crime da Casa da Supplicação',
  date: '1603',
  era: 'Idade Moderna',
  language: 'Português',
  description: `Títulos XI a XX do Livro Primeiro das Ordenações Filipinas: de "Dos Ouvidores do Crime da Casa da Supplicação" a "Do Scrivão da Chancellaria da Casa da Supplicação".`,
  parentCollectionId: 'ordenacoes-livro-1',
  sections: [
    {
      id: 'titulo-xi',
      title: `XI. Dos Ouvidores do Crime da Casa da Supplicação`,
      type: 'articles',
      articles: [
        { id: 'of1-txi-preambulo', number: 'Preâmbulo', text: `A 1ª edição desta Compilação dizia—nem por isso deixarão—, com suppressão da conjunção—e—, que Cabedo restabeleceu.` },
        { id: 'of1-txi-1', number: '1', text: `E para melhor e mais breve despacho dos feitos, cada hum dos ditos Ouvidores, cada feito que houver de despachar, o verá do principio até o fim, cotando cada cousa, que de substancia for, para quando houver de dar delle relação, com facilidade poder mostrar e achar o que necessario for; assi como, onde foi dada querela, ponha na margem da: Querela ; e se for Jurada, porá na margem: Jurada; e onde stiverem as testemunhas nomeadas, porá: Testemunhas ; e stando a querela perfeita, porá no fim della: Perfeita; e assi cotarão as outras cousas substancias do mesmo feito. E esta regra terão todos os Desembargadores, que feitos crimes houverem de ver.` },
        { id: 'of1-txi-2', number: '2', text: `E se for denunciação sem juramento e sem testemunhas, ou com ellas e sem juramento, assi o cotará, e porá na cota: Fallece tal cousa. E cotará o libello, conclusão, contestação, e os artigos, numerando cada hum delles, confissões, depoimentos. E em huma folha de fóra porá quaes artigos se provam, e per que maneira, e per que testemunhas, pondo em lembrança, se as testemunhas, que foram nomeadas, são perguntadas, e se faltam algumas; ou sendo perguntadas como não deviam, o communicará com seus companheiros. E parecendo-lhes que devem ser perguntadas outra vez, ou em outro lugar, onde mais livremente possam dizer a verdade, passarão para isso Cartas. E se o feito for no lugar, onde Nós stivermos, ou a cinco legoas de redor, perguntem-nas elles per si. E sendo de mais longe, parecendo-lhes que cumpre virem dar seus testemunhos á Corte, mandarão vir as que lhes parecerem necessarias para bem de justiça, se todos os Desembargadores, que ao desembargar do feito stiverem, forem nisso concordes, não sendo porém menos de cinco. E não sendo todos concordes, ou sendo no despacho menos de cinco Desembargadores, o dirão ao Regedor em Mesa grande, e com seu acordo e dos da dita Mesa, farão o que entenderem ser justiça. E as testemunhas, que per cada hum dos ditos acordos á Corte vierem, serão pagas nas despesas da Relação. E mandando-as vir de outra maneira, o Regedor as mandará pagar pelo mantimento dos Desembargadores, que as mandarem vir. E o que dito he no mandar vir as testemunhas, haverá lugar nos Corregedores da Corte em todos os outros Desembargadores. E quando assim vierem as testemunhas e inquirições, e per ellas se provar alguma cousa do feito, verão se tem contraditas, e se procedem, ou não, ou se stão provadas. E o que acharem, cotarão na margem, e de fóra em huma folha porão: Tal testemunha diz tal, em tal artigo; tem contradita; procede, ou não. E assi vá cotando e assommando o feito de fóra; e se achar, que a testemunha não diz cousa, que ao feito toque, ponha no começo della: Nihil; e acabado assi o feito de ver, e cotado, guarde a folha, que tem em memorial de fóra, e o leve á Relação, onde será despachado.` },
        { id: 'of1-txi-3', number: '3', text: `E as appellações, que vierem das Ilhas, ou de outros lugares, a que se ha de ir per mar, desembargarão primeiro, que as outras do Reino, por as partes não perderem embarcação. E as outras, que vierem do Reino, despacharão pela ordem, que vierem, o que poderão ver pelos termos das presentações, salvo nos feitos, que tiverem já conclusos, que despacharão primeiro.` },
        { id: 'of1-txi-4', number: '4', text: `E bem assi todas as Cartas, que passarem, para se haverem de fazer algumas execuções, ou diligencias nos feitos dos presos, as passem na fórma e com as clausulas, que dissemos no Título 7: Dos Corregedores da Corte dos feitos crimes, no paragrapho 23: Outrosi mandamos.` },
        { id: 'of1-txi-5', number: '5', text: `E terão cuidado de saberem, se se fazem as diligencias, que per bem de justiça são mandadas fazer. E pedirão disso conta aos Scrivães dante elles. E achando-os negligentes, procederão contra elles confórme ao que diremos no Título 24: Dos Scrivães dante os Desembargadores do Paco.` },
        { id: 'of1-txi-6', number: '6', text: `Os Ouvidores farão livros, em que ponham cada hum, quando vir os feitos e inquirições, os malefeitores, que acharem culpados, e dai-os-hão em scripto ao Corregedor da Corte, para os mandar prender e trazer, se taes pessoas e feitos forem, que se hajam de livrar na Corte, ou os mandar livrar nas terras, onde os maleficios forem feitos.` },
        { id: 'of1-txi-7', number: '7', text: `E cada hum dos ditos Ouvidores despacharão em sua mesa apartada, e não despacharão huns com outros, para o que pedirão Desembargadores ao Regedor.` },
        { id: 'of1-txi-8', number: '8', text: `E os ditos Ouvidores saberão, se os Scrivães, que ante elles screvem, guardam as Ordenações e Regimentos de seus Ofícios; e se dão livramento e despacho às partes sem delonga, ou se lhos retardam, ou lhes dão más respostas, ou levam mais do que devem levar. E achando alguns culpados, procederão contra elles, ou o digam ao Regedor, para em Relação lhes ser dada a pena, que merecerem.` },
      ],
    },
    {
      id: 'titulo-xii',
      title: `XII. Do Procurador dos feitos da Corôa`,
      type: 'articles',
      articles: [
        { id: 'of1-txii-preambulo', number: 'Preâmbulo', text: `Ao Procurador dos nossos feitos da Coroa pertence com grande diligencia e muito a mude requerer aos Desembargadores do Paço, Védores da Fazenda, Contadores, Juizes, Almoxarifes e quaesquer outros Officiaes, que lhe dêm as informações, que houverem de nossos Direitos, nos feitos, que se tratarem perante os Juizes dos nossos feitos da Coroa, ou que se houverem de ordenar per razão de nossas jurisdições, bens e Direitos, segundo informação, que lhe for dada. E razoará em os feitos, como entender que cumpre a nosso serviço, assi perante o dito Juiz, como perante outros quaesquer Juizes, que delles houverem de conhecer. E requererá aos Scrivães de nossos feitos, que lhe dêm em rol os que tem, e que se tratam ante os Juizes de nossos feitos sobre Jurisdições, Reguengos, Jugadas e outros Direitos nossos. E saberá em que tempo foram começados, e o por que se não dão nelles despacho, e o dirá a Nós, ou ao Regedor, para se dar ordem, como em breve sejam desembargados. E as inquirições, que por nossa parte houver de dar, as fará tirar com diligencia; para o que saberá dos Desembargadores do Paço, Védores da Fazenda, Juizes, Contadores e Almoxarifes a melhor informação que poder, para formar os artigos. E assi saberá per elles, ou por onde melhor poder, os nomes das testemunhas para prova de nossos Direitos, e assi para as contraditadas, ou reprovas às provas, dadas contra Nós.` },
        { id: 'of1-txii-1', number: '1', text: `E mandamos que o nosso Procurador não responda a citação alguma, que lhe em nosso nome seja feita, para começar novamente feito contra elle; nem elle mande citar em nosso nome pessoa alguma, nem se opponha, nem assista a feito algum, sem nosso special mandado. E quando souber que algum feito se trata, ou lhe parecer que deve citar alguem por cousa, que a Nós pertença, nol-o fará saber, para mandarmos o que houvermos por nosso serviço. Porém nos feitos que lhe for mandado per desembargo da Relação, que haja vista delles, poderá procurar, oppor-se, ou assistir, como lhe parecer, que confórme a direito deve fazer, e mais cumprir a nosso serviço, sem para isso ser necessário outro nosso special mandado. E postoque nos taes feitos assista, ou razoe, não serão as partes escusas de serem condenadas nas custas, se o merecerem. E não levará salario das partes, a que assistir, ou por cuja parte razoar.` },
        { id: 'of1-txii-2', number: '2', text: `E nos feitos, em que for autor, reu, oppoente, ou assistente, será presente ao dar das vozes e desembargar delles. E bem assi será presente ao despacho das suspeições, que pelas partes, ou pelo dito nosso Procurador forem postas a quaesquer Desembargadores, que forem Juizes, e conhecerem dos ditos feitos e causas, em que elle seja parte, assistente, ou oppoente; e não sendo presente aos desembargos, que nos ditos feitos e suspeições forem postos, sejam nullos.` },
        { id: 'of1-txii-3', number: '3', text: `E poder-se-há oppor e assistir em quaesquer feitos e causas, que se tratarem na Casa da Supplicação per razão de alguns Juizes Ecclesiasticos, ou Apostolicos quererem impedir com excommunhões e censuras o effeito e execução de nossos mandados, e sentenças dadas em nossas Relações. E requererá sobre isso todo o que cumprir. E assi sobre se haverem de guardar e dar à execução as nossas Ordenações, que fallam nos que impetram em Roma Beneficios de nossos Vassallos e naturas destes Reinos, e aceitam procurações e requerem contra elles. O que poderá fazer, postoque as partes vexadas contra a fórma das ditas Ordenações não requeiram, ou não possam ácerca disso requerer sua justiça.` },
        { id: 'of1-txii-4', number: '4', text: `E dará ordem, com que se façam as diligencias, que se mandarem fazer, e inquirições, que se moverem de tirar per Cartas dos Juizes dos nossos feitos, como nellas for conteúdo.` },
        { id: 'of1-txii-5', number: '5', text: `Informar-se-há se se tratam alguns feitos perante os Prelados ou seus Vigarios, ou outros Juizes Ecclesiasticos, que sejam contra nossos Direitos e jurisdição, para os defender por nossa parte, assi per nossas Ordenações e artigos acordados e approvados pelos Reis, que ante Nós foram, como per Direito commum e per qualquer outro modo juridico. E se vir que usurpam nossa jurisdição, ou algum Direito nosso, poderá requerer sobre isso ao Juiz dos nossos feitos, o qual he Juiz competente para conhecer, se a jurisdição pertence a nossas Justiças. E o mesmo será, quando alguma pessoa se aggravar dos Juizes Ecclesiasticos, e for leigo, ou a causa de tal qualidade, que pertença às nossas Justiças o conhecimento della, postoque as partes sejam pessoas Ecclesiasticas, porque em taes temos a nossa jurisdição fundada em Direito. E por assi ser, póde o Juiz dos nossos feitos mandar notificar aos Juizes Ecclesiasticos, que respondam a razão, que tem para tomar conhecimento dos taes casos, por assi ser conforme a Direito, e sempre se praticar e usar nestes Reinos.` },
        { id: 'of1-txii-6', number: '6', text: `E quando os Juizes Ecclesiasticos não quizerem desistir de tomarem nossa jurisdição, os Juizes de nossos feitos darão Cartas áquelles, contra quem os ditos Juizes Ecclesiasticos procederem, nas quaes lhes encommendarão, que não procedam contra elles, e nellas declararão, que a jurisdição pertence a Nós. E mandarão às nossas Justiças, que não guardem seus mandados, como de Juizes incompetentes, e que não os evitem, nem prendam per suas censuras, nem levem delles penas de excomungados, nem guardem, nem executem suas sentenças. E quando os Prelados ou Juizes Ecclesiasticos, sem embargo das ditas Cartas, não quizerem deixar de proceder contra os leigos, ou não desistirem dos procedimentos, que tiverem feitos contra elles: Nós, como Rei e Senhor, os chamaremos per Cartas per Nós assinadas, stando elles fóra da Corte, e donde stá o Desembargo do Paço; e stando onde a Corte stiver, per recado nosso, para nos darem razão de como tomam nossa jurisdição, e para sobre isso serem ouvidos perante os nossos Desembargadores do Paço com o Juiz e Procurador dos nossos feitos, os quaes fallarão e disputarão sobre o caso; e não querendo o Juiz Ecclesiastico reconhecer, que a tal jurisdição pertence a Nós, se guardará o Eis o additamento:

« E o mesmo será nos feitos, que vierem por aggrávo do Juizo da Corôa da Casa do Porto ao Juizo dos Aggravos da Casa da Supplicação. E razoará em os ditos feitos, mandando-se-lhe dar vista por desembargo da Relação. E posto que elle razõe nos taes feitos se despachará no Juizo dos Aggravos. »

Pelo art. 3 deste Decreto só o Conselho de Estado he competente para conhecer dos Recursos à Corôa.

que pelos ditos Desembargadores do Paço em nosso nome for determinado.` },
        { id: 'of1-txii-7', number: '7', text: `E quando as Justiças Ecclesiasticas procederem per suas censuras contra os nossos Desembargadores e Justiças, por tirarem, ou mandarem tirar algum preso da Igreja, ao Procurador dos nossos feitos da Coroa pertence procurar e defender a nossa jurisdição na fórma acima dita.` },
      ],
    },
    {
      id: 'titulo-xiii',
      title: `XIII. Do Procurador dos Feitos da Fazenda`,
      type: 'articles',
      articles: [
        { id: 'of1-txiii-preambulo', number: 'Preâmbulo', text: `O Procurador dos feitos da nossa Fazenda irá todos os dias à Relação, para ser presente ao despacho dos feitos della, que a Nós pertence. E para o melhor poder fazer, o escusamos de continuar com o Tribunal do Conselho da Fazenda, salvo quando della for mandado chamar para o dito Conselho, ou no princípio de cada mez, como adiante diremos.` },
        { id: 'of1-txiii-1', number: '1', text: `Item, não poderá citar pessoa alguma, nem ser citado para nenhuma causa ou demanda, nem se poderá oppor, nem assistir a ella, senão per nossas Provisões. E o despacho das petições, que as partes fizerem, per que pecam licença para poderem citar o dito Procurador, ou para se oppor, ou assistir a algumas causas, pertence ao Tribunal do Conselho da Fazenda sómente; no qual, primeiro que dêm a tal licença, examinarão bem as causas, e se verá, se póde escusar fazer-se sobre ellas demanda, e determinarem-se per outra via. E parecendo que se deve conceder a tal licença, se lhe dará despacho, per o qual se fará Provi- são; e fazendo-se as ditas Provisões em outra maneira, mandamos, que se não cumpram, nem se faça per ellas obra alguma.` },
        { id: 'of1-txiii-2', number: '2', text: `Item, mandamos ao dito nosso Procurador, que em nenhum feito venha com libello, ou contrariedade, sem primeiro dar disso conta no Tribunal do Conselho da Fazenda, para ahi fazerem tomar em lembrança as ditas causas em hum livro, que nelle para isso haverá, onde se lhe dará a informação, que for necessária. E terá cuidado de ir no princípio de cada mez ao Conselho da Fazenda dar conta dos termos, em que stão os feitos, em que elle for parte, e da diligencia, que se nelle faz, e dar informação do que nelles se mais deve fazer, e pedir a que for necessária para se prover, como parecer nosso serviço.` },
        { id: 'of1-txiii-3', number: '3', text: `E mandamos, que tanto que o nosso Procurador se oppozer, ou assistir, por o que toca a nossa Fazenda, em quaesquer feitos, logo sejam remetidos ao Juizo dos ditos feitos da Fazenda, em quaesquer termos que stiverem, sem mais Juiz algum tomar delles conhecimento, assi em todos os Juizos de nossa Corte e Casa da Supplicação, como em outros quaesquer de nossos Reinos e Senhorios.` },
        { id: 'of1-txiii-4', number: '4', text: `Item, será presente ao despacho dos aggravos dos feitos civeis, que a Nós tocarem, que forem dante o Juiz da India e Mina à Casa da Supplicação aos Desembargadores dos Aggravos della, a quem pertencem. E razoará nelles, mandando-se-lhe delles dar para isso vista per despacho da Relação: e no dito Juizo dos Aggravos se despacharão, sem embargo de elle haver vista e razoar nelles. E assi será presente ao dar das vozes nos feitos, em que for parte, e nas suspeições, da maneira que temos dito no Titulo 12: Do Procurador da Coroa.` },
        { id: 'of1-txiii-5', number: '5', text: `E bem assi, dará ordem, com que se façam as diligencias, que se mandarem fazer, e inquirições, que se houverem de tirar per Cartas dos Juizes da Fazenda, como nellas for conteúdo.` },
        { id: 'of1-txiii-6', number: '6', text: `Item, o Procurador da nossa Fazenda não levará salario algum à custa das partes, a que assistir, ou ajudar, por cónservação de nosso direito, ou por quem razoar per despacho da Relação.` },
      ],
    },
    {
      id: 'titulo-xiv',
      title: `XIV. Do Juiz da Chancellaria da Casa da Supplicação`,
      type: 'articles',
      articles: [
        { id: 'of1-txiv-preambulo', number: 'Preâmbulo', text: `Ao Desembargador, que servir de Juiz da Chancellaria, pertence passar as Cartas das execuções das dizimas das sentenças, que se derem na Casa da Supplicação. E conhecerá dos feitos, que sobre ellas se ordenarem, e os desembargará em Relação.` },
        { id: 'of1-txiv-1', number: '1', text: `Item, dará Cartas de seguro aos Tabelliães e Scrivães, e aos outros Officiaes, de cujos Officios temos ordenado, que os Desembargadores do Paço passem as Cartas, quando as ditas pessoas as quizerem tomar, de erros, ou falsidades, que se diga terem commettido em seus Officios, ou nos casos, que aos ditos Officios tocarem, e outro Julgador as não passará, postoque sejam os Corregedores do Crime da Corte. As quaes Cartas de seguro irão dirigidas para os Juizes dos lugares, onde se disser serem os ditos erros commettidos, para perante elles se livrarem; os quaes darão appellação e aggravo para o dito Juiz da Chancellaria nos casos, em que se deve dar: e nos casos commettidos dentro das cinco legoas passará as Cartas dirigidas para si mesmo, para perante elle se livrarem. E per este modo poderá conhecer per auçãó nova dos sobreditos casos na cidade de Lisboa, onde a Casa da Supplicação stá, e cinco legoas ao redor; e fóra das cinco legoas conhecerá per appellação e aggravo nos casos commettidos no districto da Casa da Supplicação. E todos os feitos e instrumentos, assi de auçãó nova, como de appellação e aggravo, despachará em Relação: e isto, postoque os taes feitos sejam de Moedeiros, ou de pessoas, que tenham privilegio de Moedeiros, por ser o Juizo da Chancellaria limitado, e nenhum outro Julgador poder conhecer de erros de Scrivães, senão elle, nem o privilegio dos Moedeiros se estender aos taes Officiaes.` },
        { id: 'of1-txiv-2', number: '2', text: `E conhecerá dos aggravos, que vierem dos Contadores das custas e dos salarios dos Procuradores, Scrivães, Tabelliães, Porteiros e Enqueredores. E quando os Procuradores, Scrivães e Enqueredores da Casa da Supplicação quizerem demandar por seus salarios algumas partes de fóra da Corte, o Juiz da Chancellaria as poderá mandar citar, por quanto as ditas pessoas podem trazer seus contendores à Corte sobre os ditos salarios e scripturas.` },
        { id: 'of1-txiv-3', number: '3', text: `Item, conhecerá de todas as suspeições, que forem postas aos Corregedores, Ouvidores, Juizes, Justiças e Officiaes da cidade de Lisboa, e ao Juiz dos Alemães: as quáes despachará em Relação com os Desembargadores, que o Regedor para isso lhe ordenar. E sendo o dito Juiz da Chancellaria suspeito ao Official, a que se intenta a suspeição, se guardará o que fica dito no Titulo 4: Do Chancellor da Casa da Supplicação, no paragrapho 5: E sendo o Chancellor. Mas não conhecerá das suspeições, postas aos Officiaes de fóra da cidade de Lisboa, postoque sejam dos lugares, que estão dentro das cinco legoas. Nem conhecerá das suspeições dos Officiaes do lugar, em que a Casa da Sup- plicação stiver, quando por algum caso se mudar da dita cidade; porque então conhecerão as Justiças ordinarias, confórme a nossas Ordenações.` },
        { id: 'of1-txiv-4', number: '4', text: `Item, quando algum Contador das custas for suspeito, ou por algum impedimento não poder fazer a conta, ou depois de feita, as partes allegarem erros sobre ella, commetterá a tal conta a huma pessoa, que bem e sem suspeita a possa fazer. E no que tocar aos erros da dita conta, elle conhecerá delles, e determinará per si só o que lhe bem parecer, postoque seja entre pessoas dos Mestrados. E o Chanceller dos Mestrados se não entremetterá nos ditos casos de erros das custas, quando as sentenças forem dadas por outros Julgadores, e não pelo mesmo Chanceller. E do que o dito Juiz da Chancellaria determinar per si só, assi neste caso, como nos outros todos, em que lhe não he ordenado, que despache em Relação, poderão as partes agravar per petição para a Relação, sem por isso pagarem dinheiro do agravo.` },
        { id: 'of1-txiv-5', number: '5', text: `E não conhecerá de culpas e erros de Scrivães e Officiaes culpados em autos de residencia, por quanto o despacho dos ditos autos, que vem per residencia, pertence aos Desembargadores, a quem o Nós commettermos, e não ao Juiz da Chancellaria.` },
        { id: 'of1-txiv-6', number: '6', text: `E em todo o caso, que a seu Officio pertencer, poderá mandar citar fora da cidade de Lisboa, onde a Casa da Supplicação stá, e cinco legoas ao redor. E assi poderá dar licença à parte, ou a qualquer pessoa em seu nome, para poder citar dentro da cidade perante huma testemunha ao menos, parecendo-lhe ser necessário; e a tal citação será valiosa.` },
        { id: 'of1-txiv-7', number: '7', text: `E assi tomará conhecimento das appellações, que vierem à Casa da Supplicação sobre erros de Scrivães da Fazenda de todo o Reino, vindo as taes appellações dante os Corregedores, Ouvidores e Juizes Ordinarios: mas vindo dante os Contadores e Almoxarifes, e outros Officiaes da dita Fazenda, não tomará dellas conhecimento, por quanto pertencem aos Juizes da Fazenda.` },
      ],
    },
    {
      id: 'titulo-xv',
      title: `XV. Do Promotor da Justiça da Casa da Supplicação`,
      type: 'articles',
      articles: [
        { id: 'of1-txv-preambulo', number: 'Preâmbulo', text: `Ao Desembargador da Casa da Supplicação, que servir de Promotor da Justiça, pertence requerer todas as cousas, que tocam à Justiça, com cuidado e diligencia, em tal maneira que por sua culpa e negligencia não pereça. E a seu Officio pertence formar libellos contra os seguros, ou presos, que por parte da Justiça hão de ser accusados na Casa da Supplicação per acordo da Relação. E levará de cada libello cem réis; e onde houver querela perfeita, ou quando o seguro confessar o malefício na Carta de seguro, em cada hum dos ditos casos o faca per mandado dos Corregedores da Corte dos feitos crimes, ou de qualquer outro Desembargador, que do feito conhecer. O qual libello fará no caso da querela o mais breve que poder, confórme a ella. Porém nos casos, onde não houver querela, nem confissão da parte, porá sua tenção na devassa, parecendo-lhe, que per ella se não deve proceder, para com elle dito Promotor se ver em Relação, se deve ser accusado, preso, ou absoluto. E assi fará nos ditos feitos quaesquer outros artigos e diligencias, que forem necessárias por bem da Justiça. Porém não razoará os ditos feitos em final, salvo em algum feito de importancia, sendo-lhe mandado per acordo da Relação.` },
        { id: 'of1-txv-1', number: '1', text: `Item, será obrigado ver todas as inquirições devassas, que vierem à Corte aos Serviães do Crime della, os quaes serão obrigados a lhas entregar do dia, que as receberem, a oito dias, sob pena de privação de seus Officios. E tanto que o dito Promotor vir qualquer das ditas inquirições, tirará a rol todas as pessoas, que per ellas achar culpadas; o qual rol mostrará a hum dos Corregedores da Corte, e lhe requererá, que os mande prender, e que proceda contra elles.` },
        { id: 'of1-txv-2', number: '2', text: `Item, o dito Promotor entregará as Cartas, que saírem dos feitos da Justiça, e assi as dos presos pobres e desamparados, e todas as outras, que a bem da Justiça pertençam, aos Caminheiros da dita Casa, que as levem aos lugares, para onde forem dirigidas, e tragam logo certidão da obra e diligencia, que per ellas fizerem. E o Solicitador da Justiça porá em lembrança perante o Promotor o dia, em que as ditas Cartas foram dadas aos Caminheiros, e o tempo, em que com as respostas dellas tornaram, para se ver se pozeram nisso a diligencia que deviam. E os que forem negligentes, apontal-os-ha o dito Solicitador, e dil-o-ha ao Regedor, o qual lhes descontará de seus mantenimentos aquillo, que por suas negligencias não mereceram.` },
        { id: 'of1-txv-3', number: '3', text: `Terá assi mesmo cuidado de ver nas respostas, que os Caminheiros trouxerem, se os Corregedores, Juizes, ou quaesquer outras pessoas, a que as Cartas iam dirigidas, foram negligentes em cumprir o que lhes per ellas era mandado, e requerer aos Julgadores, per quem taes Cartas passaram, que procedam contra elles. E todavia mande cumprir tudo o que das ditas Cartas ficou por fazer.` },
        { id: 'of1-txv-4', number: '4', text: `Item, o Promotor ha de dar certidões aos Caminheiros, como tem servido como deviam, para per ellas o Regedor lhes mandar pagar os mantenimentos.` },
        { id: 'of1-txv-5', number: '5', text: `E irá com o Solicitador da Justiça em o primeiro dia de cada mez às cadeas, e tomarão em rol todos os presos, que nellas houver, para o Regedor lhes mandar dar livramento com brevidade.` },
        { id: 'of1-txv-6', number: '6', text: `E mandamos, que em nenhuma cidade, villa, ou lugar haja Promotor da Justiça, salvo nas Casas da Supplicação e do Porto, e assi nas Correições em cada huma haverá hum Promotor dado per Nós. Porque nas outras cidades, villas e lugares o Tabellião, ou Scrivão, que fôr do feito, fará o libello, e dará as testemunhas, como se contém no quinto Livro, no Titulo 124: Da ordem do Juizo nos feitos crimes. E esta mesma ordem de dar as testemunhas terão os ditos Promotores. E do que o Tabellião ou Scrivão fizer como Promotor, não lhe será contado salario de Promotoria, sómente lhe contarão as regras, como outra scriptura do feito, que como Tabellião serve.` },
      ],
    },
    {
      id: 'titulo-xvi',
      title: `XVI. Do Juiz dos feitos da Misericordia e Hospital de Todos os Santos da cidade de Lisboa`,
      type: 'articles',
      articles: [
        { id: 'of1-txvi-preambulo', number: 'Preâmbulo', text: `Ao Desembargador da Casa da Supplicação, que for Juiz dos feitos da Misericordia e Hospital da cidade de Lisboa, pertence conhecer dos feitos, que se tratarem entre partes sobre as cousas da dita Misericordia, e sobre os bens e propriedades do dito Hospital, e dos que a Misericordia e Hospital moverem contra algumas partes, ou as partes contra as ditas Casas sobre bens, propriedades e cousas dellas, e os processará por si só, e as interlocutorias, de que per bem das Ordenações se póde agravar per petição, ou per instrumento de agravo, e assi as sentenças finaes despachará em Relação com os Desembargadores, que lhe o Regedor der. E depois de os feitos starem conclusos em final, o dito Juiz porá sua A Confraria da Misericordia, creada á instancias da Rainha D. Leonor, mulher de D. João II, em 1492, obteve desde o seu começo para si privilégios Pontificios e Reaes, sendo um delles o ter Juiz privativo em Tribunal Superior, precedendo aos mais Juizes.

tenção, e assi os mais Desembargadores, que pelo Regedor lhe forem dados. E tanto que tres forem confórmes nas tenções, porão a sentença confórme a ellas, e se cumprirá e dará á execução, sem mais appellação, nem aggravo de qualquer quantia, ou valia que seja. E o dito Juiz screverá a sentença, postoque seja vencido; e quando se tirar do processo, irá per elle assinada.` },
        { id: 'of1-txvi-1', number: '1', text: `E quanto ás outras interlocutorias e mandados, de que se não podem aggravar per petição, ou instrumento, as despachará per si só, e as partes poderão dellas aggravar no auto do processo. E quando o feito stiver concluso em final, os Desembargadores, antes de porem final sentença, proverão em Relação sobre os aggravos do auto do processo, que as partes requererem, que se despache. E depois de cumpridos os despachos, que se pozerem sobre os ditos aggravos, despacharão os ditos feitos finalmente na maneira sobredita.` },
        { id: 'of1-txvi-2', number: '2', text: `E fará as demarcações e medições de todos os bens e propriedades do dito Hospital, e das Capellas, que se a elle annexaram antigamente, por não terem Administradores, a que pertencesse a administração dellas. As quaes medições e demarcações fará, citadas as partes, com que os bens partirem e confrontarem, e com as mais solemnidades, que de Direito se requerem. E movendo-se algumas duvidas ácerca das ditas medições e demarcações, conhecerá dellas, e as determinará e as despachará em Relação pela maneira acima declarada sem appellação, nem aggravo, para, depois de acabadas, se lançarem no livro do Tombo dos bens e propriedades do Hospital, que para isso ha, com o traslado dos titulos das ditas propriedades.` },
        { id: 'of1-txvi-3', number: '3', text: `E o dito Juiz não entenderá no governo e administração da Misericordia e Hospital, nem nos arrendamentos, nem na despesa e receita das esmolas, rendas e foros, que tiverem, nem nas pagas e satisfações dos Officiaes e pessoas, que as ditas Casas servirem, porque isso pertence ao Provedor e Irmãos.` },
        { id: 'of1-txvi-4', number: '4', text: `E se ao Provedor e Irmãos parecer, que he necessario entender algum Letrado em alguma cousa, que tocar ao governo e administração do Hospital e Misericordia, o dito Desembargador o fará per sua commissão, como seu Ouvidor, e despachará as ditas cousas com o parecer do Provedor e de tres Irmãos da mesa ao menos, de maneira que sejam cinco no despacho; e do que pela maior parte delles for determinado, não haverá appellação, nem aggravo.` },
        { id: 'of1-txvi-5', number: '5', text: `E dos feitos, que tocam ás Capellas da cidade de Lisboa e seu Termo, não tomará conhecimento, nem entenderá nas contas e cousas, que ás ditas Capellas pertençam, nem em encarrego de Morgados, porque isso pertence ao Provedor das Capellas e Residuos da mesma cidade.` },
        { id: 'of1-txvi-6', number: '6', text: `E quando algum herdeiro de algum defunto tangomão, que fallecesse nas partes de Guiné, demandar ao Hospital, para que lhe restitua a fazenda, que do tal defunto ficou, e que o Hospital recadou por lhe pertencer, e lhe ser applicada per Provisões e Regimentos dos Reis nossos antecessores, por o tal herdeiro dizer, que não foi citado, nem requerido, ou que faltou alguma solemnidade das que confórme a Direito se requerem antes das ditas fazendas serem julgadas por perdidas, e se poderem entregar ao dito Hospital, a que são applicadas: o dito Juiz procederá ordinariamente, ouvindo ácerca disso o Procurador do Hospital, até no caso tomar final determinação, a qual não publicará, sem primeiro no dar do caso e della conta. E fazendo-o em outra maneira, as sentenças, em que se não fizer menção, como dellas nos foi dado conta, se não darão á execução.` },
        { id: 'of1-txvi-7', number: '7', text: `E o Juiz do Hospital fará as audiencias ás partes no lugar, onde se fazem as da Casa da Supplicação, dous dias em cada semana, ás horas, que o Regedor ordenar.` },
      ],
    },
    {
      id: 'titulo-xvii',
      title: `XVII. Do Meirinho Mór`,
      type: 'articles',
      articles: [
        { id: 'of1-txvii-preambulo', number: 'Preâmbulo', text: `O Meirinho Mór deve ser homem muito principal e de nobre sangue, que as cousas de muita importancia, quando lhe per Nós forem mandadas, ou per nossas Justiças requeridas, possa bem fazer.` },
        { id: 'of1-txvii-1', number: '1', text: `E a seu Officio pertence prender pessoas de stado, e grandes Fidalgos e Senhores de terras, e taes, que as outras Justiças não possam bem prender. E assi levantar forças, que per as taes pessoas sejam feitas, quando per Nós lhe for mandado.` },
        { id: 'of1-txvii-2', number: '2', text: `Item, ao Meirinho Mór pertence pôr de sua mão hum Meirinho, que ande continuadamente na Corte, o qual será Scudeiro de boa linhagem, e conhecido por bom, e posto per nossa auctoridade, e de que tenhamos conhecimento, para o approvar por pertencente para servir no dito Officio.` },
      ],
    },
    {
      id: 'titulo-xviii',
      title: `XVIII. Do Almotacé Mór`,
      type: 'articles',
      articles: [
        { id: 'of1-txviii-preambulo', number: 'Preâmbulo', text: `O Almotacé Mór ha de andar continuadamente em nossa Corte; e terá cuidado de buscar tantos e taes Regatães, com que a Corte sempre seja abastada de todos os mantimentos, e que se obriguem a servir com as mais azemals e melhores, que poderem. E lhes dará Cartas de seus privilegios, per elle assinadas, as quaes passarão em nosso nome, e irão à ementa, os quaes privilegios fará inteiramente guardar; e aos ditos Regatães se não guardarão os ditos privilegios, até terem as Cartas delles passadas pela nossa Chancellaria: os quaes Regatães elle mandará assentar em hum livro, que para isso terá, para saber quantos são, e para se haver de prover acerca de seus serviços, segundo a necessidade, que disso houver. E bem assi os constrangerá, que cumpram em todo o que são obrigados, assi pelas Cartas de seus privilegios, como per este Regimento.` },
        { id: 'of1-txviii-1', number: '1', text: `E serão obrigados os Regatães trazer à nossa Corte em qualquer lugar, que Nós stivermos, pão, vinho, carne, pescado e todos os outros mantimentos abastadamente, que necessarios forem, os quaes não trarão de dentro de cinco legoas, donde stivermos: e achando-se que os trouxeram de dentro de cinco legoas, mandamos, que sejam perdidos, ametade para as despesas da almotaçaria, ou para algumas obras publicas do lugar, onde Nós stivermos, que a Nós bem parecer, e a outra para o Meirinho da Corte, quando elle accusar; e quando não accusar, não leve mais que a quarta parte, e quem accusar, a outra quarta parte. E esta defesa não haverá lugar, quando Nós andarmos caminho: porque então poderão trazer os ditos mantimentos a huma legoa de redor. E outrossi não haverá lugar nos pescados, os quaes os ditos Regatães poderão comprar em quaesquer portos de mar, ou rios, postoque Nós em elles, ou perto delles stemos. E os ditos Regatães venderão os mantimentos, que assi trouxerem d'alem do dito limite, por almotaçaria, que o Almotacé Mór lhes porá, segundo lhe justo parecer. E defendemos que se não partam da Corte, em licença do Almotacé Mór, o qual lha dará, se lhe parecer necessario, deixando porém seus mancebos Vir à ementa, i. e., receber o passe ou ordem, segundo a ementa.

e bestas, que sirvam na Corte, em quanto elles fôrem absentes.` },
        { id: 'of1-txviii-2', number: '2', text: `E aos Regatães e vendeiros dos lugares, onde formos, o Almotácé Mór fará vender os mantimentos pelo Regimento e stado da terra, em que estavam antes de nossa chegada. E sobrevindo alguma mór carestia, fallará comnosco, para Nós provermos ácerca do crescimento dos preços.` },
        { id: 'of1-txviii-3', number: '3', text: `E o Almotácé Mór saberá de Nós os lugares, per onde e para onde havemos de ir, para mandar recado a cada hum delles, que façam prestes mantimentos em tal maneira, que quando chegarmos, haja em abastança o que for necessário. E tanto que chegarmos ao lugar, faça ajuntar os Juizes, Vereadores e Procurador e Almotácés, e saiba delles, como stá o lugar provido de Carniceiros, Almocreves, Padeiras, Taverneiros, e de outras cousas, que necessárias são para mantimento de nossa Corte. E proverá onde achar falta do necessário, e obrigará a cada hum dos sobreditos, que sirva com aquillo, que a seu officio pertencer. E proverá que o nosso Carniceiro corte cada dia a carne, que for obrigado.` },
        { id: 'of1-txviii-4', number: '4', text: `E em cada lugar, onde formos, haverá logo do Scrivão da Camera os nomes das vintenas, ou dos lugares e casas, se hi vintenas não houver; e saberá parte de todos os palheiros, e per seus Alvarás mandará dar palha aos da nossa Corte; e o seu Scrivão levará de cada Alvará quatro réis. E no dar da palha haverá respeito à stada, que hi houvermos de star, segundo a que na Comarca houver, dando a cada besta para vinte dias huma rede, e pagar-se-ha ao dono da palha o que pelo Almotácé Mór for taxado. E o Azemél, que tomar a palha sem Alvará, ou sem a pagar, seja preso, e da cadea pague quinhentos réis, ametade para quem o accusar, e a outra para o dono da palha.` },
        { id: 'of1-txviii-5', number: '5', text: `E queremos, que cada Lavrador, que lavrar com huma charrua, ou com hum arado, e dahi para cima com trilhoada, ou singel, faça palheiro da palha, que houver, de que se não ha de aproveitar. E qualquer que palheiro não fizer, e deixar perder a palha, pague de pena quatrocentos réis. E isto se entenda em Termo de Lisboa, Cintra, Alemquer, Santarem, Torres-Novas, Coruche, Salvaterra, Benavente, e assi em os outros lugares, a que for mandado dizer pelo Almotácé Mór, que Nós havemos de ir ter o inverno.` },
        { id: 'of1-txviii-6', number: '6', text: `O Almotácé Mór mandará pôr huma balança publica com pesos à porta do açougue, onde o nosso Carniceiro cortar a carne, com a qual stará o Porteiro da Almotaçaria, ou hum homem do Meirinho, para ver se pesa bem, e como deve, a carne, que corta. E achando, que não pesa bem, e como deve, haja as penas, que forem postas pelo Regimento da cidade, ou villa, onde isso for, aos que são comprehendidos em não pesar bem. E da pena do dinheiro haverá ametade o que tiver a balança, e a outra será para a piedade. E esta mesma maneira terão com os Carniceiros das villas e lugares, onde stivermos, quando a balança do Concelho hi não shver.` },
        { id: 'of1-txviii-7', number: '7', text: `Quando o Almotácé Mór vir que he necessário, fará vir os mantimentos per seus Alvarás dos termos dos lugares, onde stivermos, e assi das Comarcas de redor, não passando de oito legoas. E a cada vintena dará certidão do que trouxerem, feita pelo Scrivão de seu cargo. E se alguma pessoa em particular quizer certidão do que trouxe, lha dará. E das ditas certidões não levará o Scrivão cousa alguma, por quanto por esse respeito lhe foi acrescentado o mantimento.

«Em muitas Ordenações ha applicações de penas para captivos, e em outras para despezas da Relação, e nestas não ha duvida. Ha tambem algumas penas, que se applicão para a Arca da Piedade, e estas parece que se devem entregar no Desembargo do Paço, porque assim se acha expressamente no § 22 do Regimento do Presidente.»` },
        { id: 'of1-txviii-8', number: '8', text: `E se algum tomar per força alguns mantimentos ou bestas nos lugares e Comarcas, onde stivermos, pagará as penas, que diremos no segundo Livro, no Titulo 50: Que os Senhores de terras, nem outras pessoas não tomem mantimentos: e das ditas penas serão quinhentos réis (se a tanto chegarem as penas), ametade para as despesas da Almotaçaria, e a outra para o Meirinho da Corte. E o que mais for de quinhentos réis nas ditas penas, será applicado para as partes, ou lugares ahi ditos.` },
        { id: 'of1-txviii-9', number: '9', text: `Havemos por bem, que todos os que de alem de cinco legoas do lugar, onde Nós stivermos, trouxerem mantimentos à Corte, não paguem mais que meia Sisa, com tanto que não sejam moradores dentro das ditas cinco legoas. Porém se os que morarem dentro das cinco legoas, forem pelos mantimentos além das cinco legoas per constrangimento, pagarão sómente a meia Sisa, com tanto que os não tragam dos termos dos lugares, onde viverem, postoque os termos sejam além das cinco legoas. E vendel-os-hão em lugar apartado nos lugares, onde bem se póde fazer, em maneira que se não misturem com os da villa: os quaes venderão pelo miudo às pessoas, que os houverem mister, e não a Regatães, nem a outras pessoas para revender; e se os venderem em grosso, paguem toda a Sisa. E isto, que dizemos do pagar da meia Sisa, não se entenderá, quando Nós stivermos na cidade de Lisboa.` },
        { id: 'of1-txviii-10', number: '10', text: `E defendemos aos das villas e lugares, onde stivermos, e assi aos Regatães, que não comprem para revender cousa alguma dos ditos mantimentos. E os que o contrario fizerem, percam o que assi comprarem, ametade para quem os accusar, e a outra para a piedade. E isto além das penas, que per nossas Ordenações forem postas aos que compram para revender. E quando o Almotaçé Mór vir que os ditos mantimentos são poucos, mande-os repartir.` },
        { id: 'of1-txviii-11', number: '11', text: `Ao Almotaçé Mór pertence mandar nos lugares, onde a Corte stiver, cumprir as posturas feitas sobre canos, fontes, chafarizes, poços e esterqueiras: e mandar penhorar os Almotaçés, que achar negligentes, cada hum por trezentos réis por cada vez, a qual pena será ametade para as despesas da Almotaçaria, e a outra para o Meirinho. E não achando sobre isso posturas, elle com os Officiaes desse lugar em Camera façam postura, e ponham as penas, que lhes bem parecer, as quaes logo fará apregoar e cumprir.` },
        { id: 'of1-txviii-12', number: '12', text: `E bem assi mandará pregoar, tanto que a algum lugar chegarmos, que tenham os visinhos as praças e ruas limpas, e que ninguem lance sugidade alguma nos ditos lugares, sob a pena, que lhe bem parecer, não passando de quinhentos réis, e mais serem obrigados a pagar o que custar a alimpar a dita sugidade.` },
        { id: 'of1-txviii-13', number: '13', text: `Outrosi ao Almotaçé Mór pertence mandar alimpar e refazer os caminhos, calçadas e pontes nos lugares, onde stivermos, e de redor até cinco legoas, constrangendo para isso os Officiaes dos Concelhos.` },
        { id: 'of1-txviii-14', number: '14', text: `E para o Almotaçé Mór cumprir inteiramente o que pertence a seu Officio, mandamos ao Meirinho de nossa Corte, e aos Corregedores das Comarcas, Ouvidores dos Mestrados, e a todos os Juízes e Justiças, Alcaides e Meirinhos das cidades, villas e lugares de nossos Reinos, que cumpram seus mandados ácerca do que pertence a seu Officio, como e pela maneira que cumprem os mandados dos Corregedores da Corte. E da condenação das penas não haja delle appellação, nem aggravo até quantia de mil réis.` },
        { id: 'of1-txviii-15', number: '15', text: `Mandamos, que todas as penas de dinheiro, que elle pozer nas cousas, que a seu Officio pertencem, ametade seja para o Meirinho de nossa Corte, e a outra para as despesas da Almotaçaria. E para isto D. Affonso II foi o introductor do imposto, e D. Affonso V o que regulou a cobrança por meio de um Regimento de 27 de Setembro de 1476, que D. Sebastião reformou. São os celebres Artigos de Sisas, em grande parte em vigor.

Foi a princípio um tributo temporário, com destino às despesas da guerra.

que dito he, lhe damos jurisdição e alçada até a dita quantia de mil réis.` },
        { id: 'of1-txviii-16', number: '16', text: `O dito Almotacé Mór não póde fazer correição das cousas sobreditas, que a seu Officio pertencem, senão no lugar, onde Nós stivermos, ou nossa Corte, e até cinco legoas de redor.` },
        { id: 'of1-txviii-17', number: '17', text: `E terá hum Porteiro, para fazer as cousas, que lhe mandar, no que a seu Ufficio pertencer, o qual haverá mantimento e vestiaria, assi como o hão os Porteiros dante os Corregedores da Corte.

Peso do Pão das Padeiras.` },
        { id: 'of1-txviii-18', number: '18', text: `E mandará ás Padeiras que dêm pão em abastança, segundo a ordenança, que lhe per elle será dada. E não o fazendo ellas assi, paguem as penas, em que achar que caíram, as quaes serão para as despesas da Almotaçaria, ou obras publicas do mesmo lugar, ou para o Meirinho, se primeiro as comprehender. E sendo achado pelos Almotacés do lugar, sejam para o Concelho.` },
        { id: 'of1-txviii-19', number: '19', text: `Cada alqueire de trigo, depois de feito em pão, tem de peso os pães para se venderem duzentas e sessenta onças, que são dezaseis arrateis e quatro onças, de dezaseis onças cada arratel; e confórme a isto se fará avaliação e conta de cada pão pela maneira seguinte.` },
        { id: 'of1-txviii-20', number: '20', text: `Valendo o trigo a quarenta réis o alqueire, fazendo delle dezaseis pães de hum arratel e huma quarta de onça cada pão, vem a cada pão dous réis e meio.` },
        { id: 'of1-txviii-21', number: '21', text: `Item, valendo a cincoenta réis, vem a cada pão do dito peso tres réis e hum oitavo de real.` },
        { id: 'of1-txviii-22', number: '22', text: `Item, valendo a sessenta réis, vem a cada pão a tres réis e tres quartos de real.` },
        { id: 'of1-txviii-23', number: '23', text: `Item, valendo a setenta réis, vem a cada pão do dito peso a quatro réis e tres oitavos de real.` },
        { id: 'of1-txviii-24', number: '24', text: `Item, valendo a oitenta réis, vem a cada pão do dito peso a cinco réis.` },
        { id: 'of1-txviii-25', number: '25', text: `Item, valendo a noventa réis, vem a cada pão do dito peso a cinco réis e meio e um oitavo de real.` },
        { id: 'of1-txviii-26', number: '26', text: `Item, valendo a cem réis, vem a cada pão a seis réis e hum quarto de real.` },
        { id: 'of1-txviii-27', number: '27', text: `Item, valendo a cento e vinte réis, vem a cada pão do dito peso a sete réis e meio: e este respeito se terá soldo á livra, valendo o trigo a móres preços.

Padrões da Corte.` },
        { id: 'of1-txviii-28', number: '28', text: `E mandamos, que todas as medidas, pesos, varas e covados sejam tamanhos, como os da cidade de Lisboa, e não sejam maiores, nem menores: e o Almotacé Mór trará comsigo os Padrões de todos os pesos e medidas, os quaes se farão á custa de nossa Chancellaria, e dahi se pagará huma besta para os levar; e em cada hum anno duas vezes, huma em Janeiro, e outra em Julho, no lugar, onde stivermos, fará afilar e igualar áquelles, que por necessidade de seus Officios hão de ter pesos, ou medidas, per que compram e vendem, assi da Corte, como do dito lugar. E qualquer que for comprehendido per duas testemunhas, ou per sua confissão, com medida ou peso não marcado e não concertado e concordante com o Padrão, ou postoque seja justo e concertado com o Padrão, se marcado não for, pague duzentos e oitenta réis, e mais seja preso e punido confórme a nossas Ordenações e Direito, segundo a falsidade, ou malicia, em que for achado. Porém no caso em que for achado o dito peso e medida marcada, e não concordante com o Padrão, se se mostrar que foi por culpa do Affilador, será relevado da dita pena, e o Affilador a pagará: e levará o Almotacé Mór de afilar os pesos e medidas o que se acostumar levar nos lugares, onde stivermos.` },
        { id: 'of1-txviii-29', number: '29', text: `E os Carniceiros e Pescadeiras, assi da Corte, como do dito lugar, serão obrigados a afiliar os pesos cada dous mezes huma vez.` },
        { id: 'of1-txviii-30', number: '30', text: `Se os pesos e medidas forem marcadas com as marcas do Concelho, ou com a marca, que traz o Almotacé Mór, e não Até o fim do seculo xiv os Portuguezes tiverao a moeda libra, dividida em vinte soldos.

forem justos e concertados com os Padrões, se no almude de vinho for achado erro de canada, pague aquelle, em cujo poder for achado, duzentos e oitenta réis: e por erro de meia canada, cento e quarenta réis: e por erro de quartilho no almude, setenta réis: e dahi para baixo não pagará cousa alguma.` },
        { id: 'of1-txviii-31', number: '31', text: `E se na arroba for achado de erro hum arratel, pague de pena duzentos e oitenta réis: e por erro de meia arratel na arroba pague cento e quarenta réis: e dahi para baixo, soldo à livra.` },
        { id: 'of1-txviii-32', number: '32', text: `E se na vara, ou covado for achado erro de dous dedos, pague aquelle, em cujo poder for achado, duzentos e oitenta réis: e por erro de hum dedo, cento e quarenta réis: e por erro de meio dedo, setenta réis.` },
        { id: 'of1-txviii-33', number: '33', text: `Se no marco de prata for achado erro de meia onça, pague aquelle, em cujo poder for achado, quinhentos e sessenta réis: e por erro de quarto de onça pague duzentos e oitenta réis: e por erro de oitava de onça pague cento e quarenta réis: e por erro de meia oitava de onça pague setenta réis: e dahi para baixo a esse respeito. E nos pesos de ouro, se for peso de cruzado, e for em elle achado erro de hum grão, pague aquelle, em cujo poder for achado, cento e quarenta réis: e por erro de dous grãos pague duzentos e oitenta réis: e dahi para cima, a esse respeito. E se for peso de qualquer outra moeda de ouro, e for erro de hum grão, pague setenta réis: e por erro de dous grãos, cento e quarenta réis: e dahi para cima, a esse respeito: e de grão para baixo, não deve haver pena nos pesos de ouro.` },
        { id: 'of1-txviii-34', number: '34', text: `E quanto às outras medidas e pesos miudos, que aqui não são declarados, que forem marcados e não concertados com o Padrão, guarde-se ácerca disso a Postura, ou usança de qualquer cidade, villa, ou lugar, em que Nós stivermos: e não se levem outras móres penas, do que pelas ditas posturas, ou usanças se soem levar: e estas penas, sejam para as despesas da Almotaçaria, sendo o Almotacé Mór o que almotaçaria, sejam para o Meirinho, se primeiro os ditos erros achar: e sendo achados pelos Almotacés das cidades, villas, ou lugares, sejam as ditas penas para os Concelhos, e além disto as pessoas, em cujo poder as ditas medidas, ou pesos forem achados, sejam presos e punidos per Direito segundo a falsidade, ou malicia, em que forem achados.` },
        { id: 'of1-txviii-35', number: '35', text: `O Meirinho da Corte poderá trazer Padrões de pesos e medidas, para ver mais a miude, se os Regatães da Corte pesam e medem verdadeiramente: e achando-os em erro, leve-lhes toda a pena. Porém o Almotacé Mór proveja cada mez os Padrões do dito Meirinho, e outrosi se o fez bem: e se achar que o fez como não deve, applique para as obras públicas as penas de quem o maleizer, e diga-o ao Para o castigarmos como merecer.

Padrões dos Concelhos.` },
        { id: 'of1-txviii-36', number: '36', text: `E porque os Officiaes dos Concelhos saibam quaes e quantos padrões, medidas e pesos são obrigados ter, e isso mesmo as pessoas, que per razão de seus Officios são obrigados ter pesos e medidas, o declaramos na maneira seguinte. Em as cidades e villas de nossos Reinos e Senhorios, que fôrem de quatrocentos visinhos, e dahi para cima, terão os Padrões de metal seguintes, convém a saber, hum quintal, que pesa cento e vinte oito arrateis de dezaseis onças o arratel, e tem em si dezaseis peças, convém a saber, a maior peça, que he a caixa, com sua coberta do mesmo metal, que pesa meio quintal. Item, tem outra peça de arroba. Item, outra peça de meia arroba. Item, outra peça de quarta, que pesa oito arrateis. Item, outra peça de oitava, que pesa quatro arrateis. Item, outra peça, que pesa hum arratel. Item, outra peça, que pesa meio arratel, que he hum marco, que são oito onças. Item, outra peça, que pesa quarto de arratel, que he meio marco, que são quatro onças, que he oitava de arratel. Item, outra peça, que pesa huma onça. Item, outra, que pesa meia onça. Item, outra, que pesa duas oitavas. Item, outra, que pesa huma oitava. Item, duas peças de meia oitava cada huma.` },
        { id: 'of1-txviii-37', number: '37', text: `E os Concelhos, que fôrem de duzentos visinhos até quatrocentos, terão sómente meio quintal, e todos os pesos dahi para baixo acima declarados. E os Concelhos, que fôrem de duzentos visi- nhos, e dahi para baixo terão sómente huma arroba, e todos os outros pesos de arroba para baixo, que ficam acima declarados. E não serão obrigados a ter pesos nenhuns de ouro.` },
        { id: 'of1-txviii-38', number: '38', text: `Item, todas as cidades e villas de nossos Reinos e Senhorios, de qualquer numero de visinhos que sejam, terão Padrão de vara e covado, e medidas de páo de alqueire, meio alqueire, quarta de alqueire, e medidas de vinho, almude, meio almude, canada, meia canada, quartilho, meio quartilho. E medidas de azeite de alqueire, meio alqueire e quarta de alqueire. E as outras medidas miudas, segundo costume dos lugares.` },
        { id: 'of1-txviii-39', number: '39', text: `E estes Padrões de pesos e medidas starão em huma arca, ou almario do Concelho com duas fechaduras, a qual arca, ou almario, stará na Camera, e o Procurador do Concelho terá huma chave, e o Scrivão da Camera outra: e per esses Padrões se concertarão quaesquer pesos e medidas outras, que se derem para o dito Concelho, ou para fóra delle; e serão marcados da marca do Concelho, assi estes, como outras quaesquer medidas, ou pesos, que per elles fizerem. As quaes marcas dos pesos e medidas starão com os Padrões bem guardadas na dita arca, ou almario. E serão avisados, que os ditos Padrões não sairão fóra da dita arca, sómente para a Casa da Camera, quando forem necessários. E não os emprestarão a nenhuma pessoa, nem para per elles afilarem outros fóra da Camera, nem para per elles pesarem, sómente nella, como dito he. E por cada vez que o contrário fizerem, pagarão mil réis os Officiaes, que nisso forem culpados; a qual pena será para as despesas da Almotaçaria, ou para o Meirinho da Corte, se primeiro os comprehender na tal culpa, ou para o Concelho, se o Procurador do Concelho o primeiro requerer. Porém os Afiladores terão outros pesos e medidas concordantes com os sobreditos, para per elles afilarem ao Concelho, tirando meia arroba, e dahi para cima, porque estes não terá o Afilador, antes quando algum quizer afilar meia arroba, e dahi para cima, irá afilar á Camera.` },
        { id: 'of1-txviii-40', number: '40', text: `E mandamos, que pessoa alguma, de qualquer stado e condição que seja, não tenha outros differentes pesos, nem per elles venda, compre, receba, nem entreguecausa alguma; e todos comprem, vendam, e entreguem per arratel de dezaseis onças, e á este respeito o quintal, em que ha cento e vinte oito arrateis das ditas dezaseis onças, e pelos outros sobreditos pesos. E qualquer que for achado ter os ditos pesos desordenados, e não afilados pelos ditos Padrões, ou com outros pesar qualquer cousa, por cada vez que nisso for comprehendido, ou lhe for provado per verdadeira prova, seja condenado nas penas, que per nossas Ordenações são postas aos que pesam com pesos falsos.

Pesos e medidas dos particulares.` },
        { id: 'of1-txviii-41', number: '41', text: `E as pessoas particulares, que são obrigadas a ter pesos e medidas, são as seguintes.` },
        { id: 'of1-txviii-42', number: '42', text: `Item, os Ourivezes terão huma pilha de quatro marcos, convém a saber, dous marcos na pilha, e dous nos outros pesos miudos.` },
        { id: 'of1-txviii-43', number: '43', text: `Os Regatães da Corte, que vendem pescado, terão oito arrateis, e quatro arrateis, e dous arrateis, e hum arratel, e meio arratel, e duas quartas de arratel, pelo Padrão da Corte. E os das cidades, villas e lugares terão estes pesos afilados pelos Padrões dos Concelhos.` },
        { id: 'of1-txviii-44', number: '44', text: `Os Carniceiros terão arroba, e meia arroba, e quarto de arroba, e quatro arrateis, e dous arrateis, e hum arratel, e meio arratel, e duas quartas de arratel.` },
        { id: 'of1-txviii-45', number: '45', text: `Os Cerieiros terão arroba, e meia arroba, e quarto de arroba, e quatro arrateis, e dous arrateis, e hum arratel, e meio arratel, e duas quartas de arratel, e dezaseis onças pelo miudo, que são hum arratel.` },
        { id: 'of1-txviii-46', number: '46', text: `Os que fazem candêas de sêvo, terão dous arrateis, e hum arratel, e meio arratel.` },
        { id: 'of1-txviii-47', number: '47', text: `Os Caldeireiros terão arroba, e meia arroba, e quarto de arroba, e quatro arrateis, e dous arrateis, e hum arratel, e meio arratel, e duas quartas.` },
        { id: 'of1-txviii-48', number: '48', text: `Os que fazem béstas de aço, terão um peso de quatro arrateis, dous arrateis, hum arratel, meio arratel, e duas quartas de arratel.` },
        { id: 'of1-txviii-49', number: '49', text: `Os Boticarios terão dous arrateis, e meio arratel, duas quartas de arratel, e dezaseis onças pelo miudo, que são arratel, e oito oitavas pelo miudo, que são huma onça, para pesarem as mézinhas.` },
        { id: 'of1-txviii-50', number: '50', text: `A Fruiteiras, que vendem fruita a peso, terão dous arrateis, hum arratel, meio arratel, e duas quartas de arratel.` },
        { id: 'of1-txviii-51', number: '51', text: `Os que vendem sabão a peso, terão arratel, meio arratel, e quarto de arratel.` },
        { id: 'of1-txviii-52', number: '52', text: `Os Marceiros e Specieiros terão arratel, meio arratel, e duas quartas de arratel, e hum arratel pelo miudo de onças e oitavas.` },
        { id: 'of1-txviii-53', number: '53', text: `Os Moleiros e Atafoneiros e Acenheiros serão obrigados ter meio alqueire e maquia, e serão affilados duas vezes no anno, como dito he, sob a dita pena.` },
        { id: 'of1-txviii-54', number: '54', text: `E estas pessoas acima scriptas serão obrigadas ter cada huma os pesos acima declarados, e não os terão dobrados. E os irão afiliar duas vezes no anno, como dito he, pelos Padrões dos Concelhos, onde forem moradores; e os que andam em nossa Corte, pelos Padrões do Almotacé Mór. Porém os Regatães, que vendem pescado, e os Carniceiros serão obrigados a afiliar cada dous mezes huma vez, como acima he dito. E qualquer das ditas pessoas, que os ditos pesos não tiver, ou tiver dobrados, ou os não afiliar no dito tempo, pague por cada vez duzentos e oitenta réis.` },
        { id: 'of1-txviii-55', number: '55', text: `Os Tecelães de panno de linho terão meia arroba, quarto de arroba, quatro arrateis, dous arrateis, hum arratel, e meio arratel, e duas quartas de arratel.` },
        { id: 'of1-txviii-56', number: '56', text: `Os Tecelães de panno de lã terão arroba, meia arroba, e quarto de arroba, quatro arrateis, dous arrateis, e hum arratel, e dous pesos de meio arratel cada hum.` },
        { id: 'of1-txviii-57', number: '57', text: `Os Tintoreiros terão huma arroba, meia arroba, quarto de arroba, quatro arrateis, dous arrateis, hum arratel, dous meios arrateis, e outro arratel, feito em onças e oitavas.` },
        { id: 'of1-txviii-58', number: '58', text: `As Tecedeiras de véos terão oito onças, quatro onças, duas onças, huma onça, e meia onça.` },
        { id: 'of1-txviii-59', number: '59', text: `Porém os ditos Tecelães e Tintoreiros e Tecedeiras não serão obrigados a afiliar seus pesos mais que huma vez em cada hum anno, no mez de Janeiro: mas se não tiverem os ditos pesos todos, por qualquer que lhe faltar, pagarão a dita pena, e assi se os não afilarem em cada hum anno ao dito tempo.` },
        { id: 'of1-txviii-60', number: '60', text: `Outrosi os Mercadores de panno de cor terão vara e covado; e os Trapeiros, que costumam vender panno de linho, ou burel, almafega, ou outra qualquer mercadoria, que se costuma vender per varas, terão varas, e as varas, ou covados serão duas vezes no anno afiliadas, huma em Janeiro e outra em Julho, pelos Padrões do Concelho, sob a dita pena.` },
        { id: 'of1-txviii-61', number: '61', text: `Os que costumam comprar, ou vender vinhos em grosso, terão almudes e meios almudes. E os que venderem vinhos atavernados, terão canadas, meias canadas, quartilhos, e meios quartilhos.` },
        { id: 'of1-txviii-62', number: '62', text: `E os que costumarem comprar e vender azeite em grosso, terão alqueire, meio alqueire, e quarta de alqueire. E os que venderem pelo miudo, terão aquellas medidas pequenas, que nas cidades, villas e lugares, onde venderem, se costumam ter.` },
        { id: 'of1-txviii-63', number: '63', text: `Porém todas as sobreditas pessoas particulares, que per este Regimento são obrigadas ter pesos, se viverem fóra das cidades, ou villas, não serão obrigadas a afilar mais que huma vez no anno, no mez de Janeiro. E não as afilando ao dito tempo, incorrerão nas sobreditas penas.` },
        { id: 'of1-txviii-64', number: '64', text: `E as pessoas, que não costumam comprar e vender per razão de seus Officios, não serão constrangidas a ter pesos, ou medidas. E aquelles, que as quizerem ter por suas vontades, não serão obrigados a as afilar, nem marcar, senão huma só vez, quando as houverem; e poderão dellas usar, em quanto boas e verdadeiras forem, depois que assi marcadas forem e afiliadas. Porém sendo-lhes achadas não marcadas, ou não justas e verdadeiras com os Padrões, incorrerão nas penas acima declaradas.` },
        { id: 'of1-txviii-65', number: '65', text: `E as sobreditas penas serão applicadas para as despesas da Almotaçaria, ou para alguma obra publica, a que Nós as applicarmos, sendo o Almotaçé Mór o que os erros achar, ou para o Meirinho da Corte, se elle os achar primeiro. E isto se entenderá, onde a Corte stiver, e não em outra parte. E sendo achadas pelos Almotaçés das cidades, villas e lugares, sejam para o Concelho.` },
        { id: 'of1-txviii-66', number: '66', text: `E as pessoas, que se sentirem aggravadas do Almotaçé Mór, se poderão aggravar per petição a Nós, para no caso mandarmos o que for justiça. E não se aggravarão delle para Tribunal algum, por quanto assi se costumou sempre.` },
      ],
    },
    {
      id: 'titulo-xix',
      title: `XIX. Do Scrivão da Chancellaria do Reino`,
      type: 'articles',
      articles: [
        { id: 'of1-txix-preambulo', number: 'Preâmbulo', text: `Quando provermos do Officio de Scrivão da Chancellaria, jurará antes de o servir, que bem e verdadeiramente o servirá, guardando inteiramente seu Regimento a serviço de Deos e nosso, e bem das partes. E nesta fórma tomará per si juramento aos que forem providos de Officios, de que na dita Chancellaria devem jurar, não sendo os Officios da qualidade, a que o Chanceller Mór per seu Regimento per si só o haja de dar; o que fará nos dias das dadas das Cartas, que com elle depois de vistas e passadas pelo Chanceller Mór se hão de dar e despachar às partes.` },
        { id: 'of1-txix-1', number: '1', text: `E tomado assi per elle o dito juramento aos taes Officiaes, assentará per sua mão, e sob seu sinal nas costas das Cartas dos Officios: Eu N. tomei per mim juramento a N. e dou disso fé. E sem isto não passará Carta de algum Officio. E se não levar a fé do dito Scrivão nas costas da dita Carta, de como lhe deu juramento da maneira que dito he, não lhe será tal Carta guardada, nem poderá servir o tal Officio. E servindo-o, o poderão pedir a Nós, como se nelle fizesse taes erros, por que per bem de nossas Ordenações o deva perder.` },
        { id: 'of1-txix-2', number: '2', text: `Item, dará as Cartas, como forem selladas, perante o Recebedor, e não sem elle. E ponha em ellas a paga per sua mão, segundo fórma do Regimento da taxa da Chancellaria. E como pozer a paga na Carta, screverá no livro, per que esse Recebedor ha de dar conta do que receber. O qual livro guardará bem, por quanto afóra essa recadação se podem dar per elle muitos despachos. E se elle duvidar ou a parte se aggravar delle, leve-a ao Chanceller Mór, o qual dará determinação pela maneira, que fica dito em seu Regimento.` },
        { id: 'of1-txix-3', number: '3', text: `E no dar das Cartas terá esta ordem. As Cartas de pergaminho, que fôrem de registro, se darão primeiro, e depois os perdões, e assi outras em papel, que tambem fôrem de registro. E após os perdões e Cartas se darão outras quaesquer Cartas, que fôrem de sello redondo, e por derradeiro se darão os Alvarás e Provisões, sem nisso intervir favor de se darem primeiro huns que outros.` },
        { id: 'of1-txix-4', number: '4', text: `Item, registrará todas as Cartas, que para registrar forem, convém a saber: todas as que passarem com sello pendente, não sendo sentenças, Cartas de seguranças Reaes, Cartas de mercês de cousas moveis. E registral-as-há de boa letra em livros, que para isso haverá, convém a saber: em hum livro registrará doações, padrões, Officios e aforamentos: e em outro todas as Cartas, que passam pelos Desembargadores do Paço: e em outro privilegios, liberdades, presentações de Igrejas, e todas as outras de quaesquer qualidades. E terá hum livro apartado, em que registrará as Cartas, per que fizermos mercê a algumas Ordens e Igrejas, que possam comprar bens de raiz.` },
        { id: 'of1-txix-5', number: '5', text: `E não consentirá, que parte alguma registre sua Carta, nem outra pessoa, mas todas as Cartas, que forem para registrar, registre-as elle, ou outros seus Scrivães, que para isso tenham nosso Alvará, e que sejam juramentados. E qualquer pessoa, que sem nosso Alvará no dito Officio screver, haverá a pena de falsario. Porém o Scrivão da Chancellaria não será desobrigado das penas, que os ditos Scrivães, que por elle screverem, merecerem por quaesquer erros, que nos ditos Officios fizerem. E desque a Carta per elle, ou pelos ditos Scrivães for registrada, a concertará, e assine per sua mão em fim do registro de cada huma Carta. E se no registro houver alguma duvida, interlinha, respançamento, ou borradura, resalve-a o dito Scrivão em fim do dito registro, e assine per sua mão de maneira, que nisso se não possa fazer falsidade, e se se fizer, que logo pareça. E tudo isto cumprirá assi o dito Scrivão principal, sob pena de privação do Officio.` },
        { id: 'of1-txix-6', number: '6', text: `E todas as Cartas que fôrem de graça, que per Nós não forem assinadas, e o forem per nossos Officiaes, que per bem de seus Officios e Regimentos as taes Cartas devem passar, ponha em huma emmenta, e a trará a Nós, ao menos duas vezes na semana. E ponha nessa emmenta todas as forças das Cartas, e per quem passam; e as que Nós mandarmos, que passem, ou não, segundo o que Nós mandarmos, assi o screverá logo na emmenta, a qual Nós assinaremos, e o dito Scrivão a guardará muito bem; e depois que per Nós for assinada, a levará, ou mandará mostrar ao Chanceller Mór, para ao tempo do sellar das Cartas as concertar com ella, e logo se tornará ao dito Scrivão.` },
        { id: 'of1-txix-7', number: '7', text: `E porque a emmenta he a maior confiança, que no dito Officio há, se o dito Scrivão for doente, ou occupado em outras cousas, que per si a não poder despachar comnosco, não dará carrego a nenhum, que a traga a Nós, salvo se for homem de Nós bem conhecido, e per nosso Alvará approvado. E aquelle, que comnosco despachar a dita emmenta, dará Cartas della, e lhe porá as pagas.` },
        { id: 'of1-txix-8', number: '8', text: `E quando acontecer, que na dada das Cartas alguma das partes não vier requerer as suas, e ficarem por dar, mandamos ao dito Scrivão, que as que ficarem, ponha todas em huma arca, de que elle tenha huma chave, e o Recebedor outra. E quando em outro dia houver de dar as Cartas, que novamente sellarem, então dem as outras, que ficarem; e as que ficarem por dar, sempre fiquem em sua guarda fechadas na dita arca, em tal maneira, que se não possam furtar, nem fazer em ellas outra maldade alguma.` },
        { id: 'of1-txix-9', number: '9', text: `Item, fará todas as Cartas dos desembargos, que pertencem ao Chanceller Mór, e screverá os processos, que forem ordenados perante elle, que a seu Officio pertencerem: e faça de maneira, que seja bem diligente nas cousas, que toquem a seu Officio, e requeira ao Chanceller Mór per seus desembargos, e falle com elle, cada vez que cumprir, sobre as duvidas, que tiver, ou quando as partes se aggravarem das pagas, como acima dito he.` },
        { id: 'of1-txix-10', number: '10', text: `E na recadação das dizimas das sentenças, que se derem na Corte pelos Officiaes, que nella andarem, quando a Corte stiver fóra da cidade de Lisboa, onde a Casa da Supplicação reside, terá a maneira, que se contém no Regimento do Scrivão da Chancellaria da dita Casa.` },
        { id: 'of1-txix-11', number: '11', text: `Mandamos ao Scrivão da Chancellaria, que ponha nas costas das Cartas e Alvarás, que per ella passarem, com o sinal da paga, os dias do mez e anno, em que forem despachados pela Chancellaria.` },
      ],
    },
    {
      id: 'titulo-xx',
      title: `XX. Do Scrivão da Chancellaria da Casa da Supplicação`,
      type: 'articles',
      articles: [
        { id: 'of1-txx-preambulo', number: 'Preâmbulo', text: `O Scrivão da Chancellaria da Casa da Supplicação dará as Cartas, como forem selladas, perante o Recebedor, e não sem elle, e porá em ellas a paga per sua mão, e screverá no livro da receita; e se houver duvida entre elle e a parte sobre a paga da Chancellaria, leve logo a Carta ao Chanceller, o qual a levará à Relação, e nella determinará a dita duvida com os Segundo Monsenhor Gordo, o pr. e §§ 1, 2 e 3 deste titulo, parece haverem sido tirados dos §§ 1, 2 e 3 do t. 35 do Codigo Manuelino, em que se tratava do Escrivão da Chancellaria da Casa do Civel, que era a privativa de Lisboa, assim como depois o ficou sendo a da Supplicação por determinação do Rey D. Felippe II.

Desembargadores, que para isso o Regedor lhe ordenar.` },
        { id: 'of1-txx-1', number: '1', text: `E quando na dada das Cartas algumas ficarem por dar, por as partes as não irem requerer, o dito Scrivão as ponha em huma arca, de que tenha huma chave, e o Recebedor outra, per maneira que se não possam furtar, nem fazer em ellas outra maldade. As quaes dará na outra dada seguinte, com as que se depois sellarem, e darão as Cartas, que ficarem de huma dada para outra.` },
        { id: 'of1-txx-2', number: '2', text: `Item, deve ser diligente, e bem mandado nas cousas, que a seu Officio pertencem, e requeira ao Chanceller, e falle com elle cada vez que cumprir, sobre as duvidas, que tiver em seu Officio, ou quando se as partes aggravarem das pagas, como dito he.` },
        { id: 'of1-txx-3', number: '3', text: `E para o dito Scrivão saber como se hão de arrecadar as dizimas das sentenças, além do que na taxa da Chancellaria he conteúdo, e assi para a todos ser notorio, ordenamos que as dizimas, vintenas, ou quarentenas de todas as sentenças se arrecadem per esta maneira. Se a sentença condenatoria não passar de quantia de trinta mil réis, o vencedor pague logo ao tirar da sentença da Chancellaria toda a dizima, que nella montar, salvo se logo ahi mostrar e fizer certo, como o condenado não tem bens, nem fazenda, per que se possa haver o que lhe he julgado, e mais a dizima, se a pagasse pelo dito condenado; porque neste caso será entregue a sentença ao vencedor, sem pagar a dizima, e ficará resguardado ao nosso Recebedor, ou Rendeiro, poder arrecadar a tal dizima pelo condenado, se depois tiver bens, per que a possa pagar. E sendo a condenação de maior quantia, tirar-se-ha a verba da dita condenação, para per ella se fazer Carta de execução, e se arrecadará a dizima, vintena, ou quarentena, que em tal caso couber, pelos bens do condenado, e não se tirar, nem desfalcará cousa alguma do que ao vencedor foi julgado. E não se achando tantos bens, per que se possa tudo haver, será primeiro pago o vencedor do que lhe for julgado, e pela mais fazenda do condenado (se a tiver) se arrecadará para Nós, ou para o Rendeiro, que nesse tempo for, a dita dizima, vintena, ou quarentena, sem por isso o condenado poder ser preso; ficando resguardado ao nosso Recebedor, ou Rendeiro, se ao tempo, que se devem arrecadar as dizimas, se não acharem bens do condenado, fazer execução pelos bens, que depois lhe forem achados, em qualquer tempo que seja.` },
        { id: 'of1-txx-4', number: '4', text: `E mandamos, que quando algum for accusado pela Justiça, e for absoluto, e que pague as custas de seu livramento, de taes custas se não pague dizima.` },
        { id: 'of1-txx-5', number: '5', text: `Nem outrosi se arrecadarão as dizimas das sentenças das partes condenadas pela primeira sentença, quando della se aggravar, antes se sobrestará na execução e arrecadação das ditas dizimas, em quanto pender o aggravo, assim como se sobrestá na causa principal.` },
        { id: 'of1-txx-6', number: '6', text: `Item, não se pagará dizima das sentenças, que os Corregedores das Comarcas e Ouvidores derem em feitos, de que conhecerem como Juizes, nos casos, em que lhes he permitido per seus Regimentos, que vierem per appellação ás nossas Relações, como diremos no Titulo 58: Dos Corregedores das Comarcas, § 23.` },
      ],
    },
  ],
};
